                { stageId: "med-s6f", topic: "Cardiac Output Calculation", module: "Practice", component: "LogicChain", skin: "Scientific", config: { data: { nodes: ["Heart rate = 72 bpm", "Stroke volume = 70 mL", "CO = HR × SV", "CO = 72 × 70", "CO = 5,040 mL/min ≈ 5 L/min"] }, initialState: {} }, validation: { type: "exact", condition: {} }, feedback: { success: "Calculation sequence correct!", error: "Multiply heart rate by stroke volume.", hint: "Normal cardiac output is about 5 liters per minute." } },
                { stageId: "med-s6g", topic: "Teach: Cardiac Cycle", module: "Assessment", component: "FeynmanPrompt", skin: "Scientific", config: { data: { prompt: "Explain what 'isovolumetric contraction' means and why it's important in the cardiac cycle.", sampleAnswer: "Isovolumetric contraction is a brief phase where the ventricles contract but no blood moves because all four valves are closed. The AV valves just closed (causing S1) and pressure is building, but it hasn't exceeded arterial pressure yet to open the semilunar valves. It's important because it represents the rapid pressure buildup needed to force open the semilunar valves and eject blood.", fixedFeedback: "Excellent explanation! You correctly identified that 'isovolumetric' means constant volume — all valves closed, pressure building rapidly. This is the critical moment when the ventricles generate enough pressure to open the semilunar valves. Your understanding of pressure dynamics is solid!" }, initialState: {} }, validation: { type: "exact", condition: {} }, feedback: { success: "Great teaching!", error: "Focus on what 'iso-volumetric' literally means.", hint: "Iso = same, volumetric = volume. All valves closed." } }
